import { useState } from 'react'
import { Helmet } from 'react-helmet-async'
import { useNavigate } from 'react-router'
import { useSearchParams } from 'react-router-dom'

import { Box, Paper, Typography, useMediaQuery, useTheme } from '@mui/material'

import NewPasswordForm from 'src/components/NewPasswordForm'

import { useResetPassword } from 'src/hooks/api/authHooks'

function ResetPassword() {
  const navigate = useNavigate()
  const theme = useTheme()
  const matches = useMediaQuery(theme.breakpoints.up('sm'))
  const [searchParams] = useSearchParams()
  const token = searchParams.get('token') ?? ''

  const [values, setValues] = useState({ newPassword: '' })
  const resetPasswordMutation = useResetPassword(token, values)

  const onClickSubmit: React.FormEventHandler<HTMLFormElement> = e => {
    e.preventDefault()

    resetPasswordMutation.mutate()
  }

  const onClickCancel = () => {
    navigate('/')
  }

  const handleChange: React.ChangeEventHandler<HTMLInputElement> = event => {
    if (event.target.type === 'password') {
      const newPassword = document.getElementById('new-password') as HTMLInputElement
      const confirmPassword = document.getElementById('confirm-password') as HTMLInputElement
      if (newPassword.value !== confirmPassword.value) confirmPassword.setCustomValidity("Passwords don't match")
      else confirmPassword.setCustomValidity('')
    }
    if (event.target.id === 'new-password') {
      setValues({ newPassword: event.target.value })
    }
  }

  return (
    <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
      <Helmet>
        <title>비밀번호 변경</title>
      </Helmet>
      <Paper
        square={!matches}
        sx={{
          my: theme.spacing(13),
          padding: 3,
          flex: 1,
          maxWidth: '360px',
          height: { xs: '90vh', sm: 'inherit' },
          [theme.breakpoints.down('sm')]: {
            my: 0,
            py: 5,
            maxWidth: '100%'
          }
        }}
      >
        <Typography variant="subtitle1" sx={{ mb: 2, textAlign: 'center' }}>
          새로운 비밀번호를 입력해주세요
        </Typography>
        <NewPasswordForm
          isForgotPassword={true}
          handleChange={handleChange}
          onClickSubmit={onClickSubmit}
          onClickCancel={onClickCancel}
        />
      </Paper>
    </Box>
  )
}

export default ResetPassword
