// eslint-disable-next-line @typescript-eslint/no-explicit-any
const Loader = (Component: React.ComponentType<any>) => (props: JSX.IntrinsicAttributes) =>
  (
    <Suspense fallback={<SuspenseLoader />}>
      <Component {...props} />
    </Suspense>
  )

interface RequireAuthProps {
  loginPath: string
  children?: JSX.Element
}

interface RequireAdminProps {
  redirectPath?: string
  children?: JSX.Element
}

interface RequireSuperAdminProps {
  redirectPath?: string
  children?: JSX.Element
}

function RequireAuth({ loginPath, children }: RequireAuthProps) {
  const isAuthenticated = useIsAuthenticated()
  if (isAuthenticated()) return children ?? <Outlet />

  // 튕겼을 때, 뒤로가기 누르면 튕기기 전 페이지로 돌아와야 함.
  return <Navigate to={loginPath} replace={true} />
}

function RequireAdmin({ redirectPath, children }: RequireAdminProps) {
  const authUser = useAuthUser()
  const { enqueueSnackbar } = useSnackbar()
  const { id } = useParams()
  const clubId = Number(id)
  const club = authUser()?.clubs.filter((c: ClubMemberForAuth) => c.id === clubId)[0]

  const isAdmin = club && ['SUPERADMIN', 'ADMIN'].includes(club.permission)

  if (isAdmin) return children ?? <Outlet />
  else enqueueSnackbar('권한이 없습니다.', { variant: 'error' })

  return <Navigate to={redirectPath ?? isAdmin === null ? '/' : `/club/${clubId}`} replace />
}

const RequireSuperAdmin: React.FC<RequireSuperAdminProps> = ({ redirectPath = '/Mypage', children }) => {
  const authUser = useAuthUser()
  const { enqueueSnackbar } = useSnackbar()
  const user = authUser()
  const isSuperAdmin = user?.permission === 'SUPERADMIN'

  useEffect(() => {
    if (user && !isSuperAdmin) {
      enqueueSnackbar('권한이 없습니다.', { variant: 'error' })
    }
  }, [enqueueSnackbar, isSuperAdmin, user])

  if (isSuperAdmin) return children ?? <Outlet />

  return <Navigate to={redirectPath} replace />
}

