import { useEffect } from 'react'
import { useAuthUser } from 'react-auth-kit'
import { useLocation } from 'react-router'
import { useRecoilState } from 'recoil'

import AssignmentIndIcon from '@mui/icons-material/AssignmentInd'
import ChevronLeftIcon from '@mui/icons-material/ChevronLeft'
import ChevronRightIcon from '@mui/icons-material/ChevronRight'
import ConfirmationNumberIcon from '@mui/icons-material/ConfirmationNumber'
import HomeRoundedIcon from '@mui/icons-material/HomeRounded'
import MenuIcon from '@mui/icons-material/Menu'
import SearchIcon from '@mui/icons-material/Search'
import { type CSSObject, Divider, IconButton, List, type Theme, styled, useMediaQuery, useTheme } from '@mui/material'
import MuiDrawer from '@mui/material/Drawer'

import type { ClubLike } from 'src/models/club'
import type { ClubMemberForAuth } from 'src/models/clubMember'

import { ClubAvatar, DrawerHeader, DrawerItem, LockBadge, NamedDivider } from 'src/components/Sidebar/SidebarItems'

import { useGetLike } from 'src/hooks/api/club'
import type { SidebarProps } from 'src/layouts/SidebarLayout'
import { isLikeBtnClickedAtom } from 'src/recoil/atom'

const openedMixin = (theme: Theme): CSSObject => ({
  width: theme.sidebar.width,
  transition: theme.transitions.create('width', {
    easing: theme.transitions.easing.sharp,
    duration: theme.transitions.duration.enteringScreen
  }),
  overflowX: 'hidden'
})

const closedMixin = (theme: Theme): CSSObject => ({
  transition: theme.transitions.create('width', {
    easing: theme.transitions.easing.sharp,
    duration: theme.transitions.duration.leavingScreen
  }),
  overflowX: 'hidden',
  width: `calc(${theme.spacing(6)} + 1px)`,
  [theme.breakpoints.up('lg')]: {
    width: `calc(${theme.spacing(8)} + 1px)`
  }
})

const Drawer = styled(MuiDrawer)(({ theme, open }) => ({
  width: theme.sidebar.width,
  flexShrink: 0,
  whiteSpace: 'nowrap',
  boxSizing: 'border-box',
  ...(open && {
    ...openedMixin(theme),
    '& .MuiDrawer-paper': openedMixin(theme)
  }),
  ...(!open && {
    ...closedMixin(theme),
    '& .MuiDrawer-paper': closedMixin(theme)
  })
}))

function Sidebar({ open, handleDrawerClick }: SidebarProps) {
  const theme = useTheme()
  const isPc = useMediaQuery(theme.breakpoints.up('lg'))
  const isNotRegisterPage = window.location.pathname != '/club/register'

  const [isLikeBtnClicked, setIsLikeBtnClicked] = useRecoilState(isLikeBtnClickedAtom)

  const authUser = useAuthUser()
  const clubs = authUser()?.clubs
  const adminClubs = clubs?.filter((c: ClubMemberForAuth) => ['SUPERADMIN', 'ADMIN'].includes(c.permission))
  const location = useLocation()

  const queryKey: ClubLike[] = authUser()?.likes ?? []
  const { data: updateLike } = useGetLike(isLikeBtnClicked, queryKey)

  const likes: ClubLike[] = updateLike ?? []

  useEffect(() => {
    if (isLikeBtnClicked) {
      setIsLikeBtnClicked(false)
    }
  }, [isLikeBtnClicked])

  return (
    <Drawer
      variant={isPc && isNotRegisterPage ? 'permanent' : 'temporary'}
      open={open}
      sx={{ zIndex: 10 }}
      onClose={handleDrawerClick}
    >
      <>
        <DrawerHeader
          sx={{
            justifyContent: open ? 'flex-end' : 'center'
          }}
        >
          <IconButton onClick={handleDrawerClick}>
            {open ? theme.direction === 'rtl' ? <ChevronRightIcon /> : <ChevronLeftIcon /> : <MenuIcon />}
          </IconButton>
        </DrawerHeader>
        <Divider />
        <List>
          <DrawerItem
            open={open}
            text="KLUB"
            icon={<HomeRoundedIcon />}
            href="/"
            selected={location?.pathname === '/'}
            theme={theme}
          />
          <DrawerItem
            open={open}
            text={open ? '동아리 검색' : '검색'}
            icon={<SearchIcon />}
            href="/search"
            selected={location?.pathname === '/search' && !location?.search.includes('type=')}
            theme={theme}
          />
          <DrawerItem
            open={open}
            text={open ? '모집 공고' : '모집공고'}
            icon={<AssignmentIndIcon />}
            href="/search/recruit"
            selected={location?.pathname === '/search/recruit'}
            theme={theme}
          />
          <DrawerItem
            open={open}
            text="쿠폰 혜택"
            icon={<ConfirmationNumberIcon />}
            href="/benefit-coupons"
            selected={location?.pathname.startsWith('/benefit-coupons')}
            theme={theme}
          />
        </List>
        {adminClubs?.length > 0 && (
          <>
            <NamedDivider open={open} theme={theme}>
              운영 중인 동아리
            </NamedDivider>
            <List>
              {adminClubs?.map((club: ClubMemberForAuth) => (
                <DrawerItem
                  key={`${club.id} ${club.name} admin`}
                  open={open}
                  text={`${club.name}`}
                  icon={<ClubAvatar name={club.name} profileImageUrl={club.profileImageUrl} />}
                  badge={<LockBadge />}
                  href={`/manage/${club.id}/member`}
                  selected={(location?.pathname + '/').includes(`/manage/${club.id}/`)}
                  theme={theme}
                />
              ))}
            </List>
          </>
        )}
        {clubs?.length > 0 && (
          <>
            <NamedDivider open={open} theme={theme}>
              활동 중인 동아리
            </NamedDivider>
            <List>
              {clubs?.map((club: ClubMemberForAuth) => (
                <DrawerItem
                  key={`${club.id} ${club.name}`}
                  open={open}
                  text={club.name}
                  icon={<ClubAvatar name={club.name} profileImageUrl={club.profileImageUrl} />}
                  href={`/club/${club.id}/profile`}
                  selected={(location?.pathname + '/').includes(`/club/${club.id}/`)}
                  theme={theme}
                />
              ))}
            </List>
          </>
        )}
        {authUser() && likes?.length > 0 && (
          <>
            <NamedDivider open={open} theme={theme}>
              내 찜 동아리
            </NamedDivider>
            <List>
              {likes?.map((like: ClubLike) => (
                <DrawerItem
                  key={`${like.clubId} ${like.name}`}
                  open={open}
                  text={like.name}
                  icon={<ClubAvatar name={like.name} profileImageUrl={like.profileImageUrl} />}
                  href={`/club/${like.clubId}`}
                  selected={(location?.pathname + '/').includes(`/club/${like.clubId}/`)}
                  theme={theme}
                />
              ))}
            </List>
          </>
        )}
        {likes?.length > 0 || <Divider />}
      </>
    </Drawer>
  )
}

export default Sidebar
