import { Helmet } from 'react-helmet-async'

import { Link as RouterLink } from 'react-router-dom'

import ArrowForwardRoundedIcon from '@mui/icons-material/ArrowForwardRounded'
import { Box, Button, Container, Typography, useMediaQuery, useTheme } from '@mui/material'

interface CatchphraseProps {
  children: React.ReactNode
}

const RegisterCatchphrase: React.FC<CatchphraseProps> = ({ children }) => {
  const theme = useTheme()
  const isNotMobile = useMediaQuery(theme.breakpoints.up('sm'))

  return (
    <>
      <Helmet>
        <title>KLUB :: All the Clubs on KLUB</title>
      </Helmet>
      <InfoSection backgroundColor={theme.colors.alpha.white[100]} isMqMatched={isNotMobile}>
        <Container maxWidth="sm" sx={{ paddingX: '5px' }}>
          <Typography
            variant={isNotMobile ? 'h1' : 'h3'}
            fontSize={isNotMobile ? 50 : 30}
            component="h1"
            gutterBottom
            sx={{ textAlign: 'center' }}
          >
            All the Clubs on KLUB!
          </Typography>
          <Button
            component={RouterLink}
            to="/service-introduction"
            endIcon={<ArrowForwardRoundedIcon />}
            sx={{
              display: 'flex',
              width: 'fit-content',
              margin: '0 auto',
              px: 0,
              borderRadius: 0,
              borderBottom: '1px solid transparent',
              '&:hover': {
                backgroundColor: 'transparent',
                borderColor: 'currentColor'
              }
            }}
          >
            KLUB 사용법 확인하기
          </Button>
          <Box textAlign={'center'} px={isNotMobile ? 0 : 2}>
            {children}
          </Box>
        </Container>
      </InfoSection>
    </>
  )
}

export default RegisterCatchphrase



interface InfoSectionProps {
  backgroundColor: string // TODO: CSS backgroundColor value type으로 설정
  isMqMatched: boolean
}

const InfoSection: React.FC<InfoSectionProps> = ({ backgroundColor, isMqMatched, children }) => {
  const theme = useTheme()

  return (
    <Box
      component="section"
      sx={{
        height: '95vh',
        backgroundColor,
        display: 'flex',
        flexDirection: isMqMatched ? 'row' : 'column',
        justifyContent: 'space-around',
        alignItems: 'center',
        gap: theme.spacing(2, 0),
        padding: theme.spacing(5, 0),
        [theme.breakpoints.down('md')]: {
          padding: theme.spacing(5, 0)
        },
        [theme.breakpoints.down('sm')]: {
          padding: theme.spacing(3, 0)
        }
      }}
    >
      {children}
    </Box>
  )
}
