export type PutUserRequestBody = Required<Pick<User, 'name' | 'nickname' | 'department' | 'phoneNumber'>>

export interface PutRequestParams {
  user: PutUserRequestBody
  token: string
}

export const putUserInformation = async ({ user, token }: PutRequestParams) => {
  await axios.put<null, AxiosResponse<null>, PutUserRequestBody>(`${process.env.REACT_APP_APIHOST}/user`, user, {
    headers: { Authorization: token }
  })
}

export const usePutUserInformation = (user: PutUserRequestBody) => {
  const { enqueueSnackbar } = useSnackbar()
  const token = useAuthHeader()()
  const client = useQueryClient()
  return useMutation(() => putUserInformation({ user, token }), {
    onSuccess: () => {
      client.invalidateQueries({
        queryKey: [user]
      })
    },
    onError: error => {
      if (error instanceof AxiosError) {
        const errorMessage = error.response?.data?.message || COMMON_MESSAGE.SERVER_ERROR
        enqueueSnackbar(errorMessage, { variant: 'error' })
      } else {
        enqueueSnackbar(COMMON_MESSAGE.UNKNOWN_ERROR, { variant: 'error' })
      }
    }
  })
}
