interface PatchMembersMutateParams {
  clubId: ClubId
  updatedMembers: ClubMemberForPatch[]
}
interface PatchMembersParams extends PatchMembersMutateParams {
  token: string
}
const patchMembersAPICall = async ({ clubId, updatedMembers, token }: PatchMembersParams) => {
  await axios.patch<null, AxiosResponse<APIMessageResponse>, ClubMemberForPatch[]>(
    `${process.env.REACT_APP_APIHOST}/club/${clubId}/member`,
    updatedMembers,
    {
      headers: { Authorization: token }
    }
  )
}
export const usePatchMembers = () => {
  const { enqueueSnackbar } = useSnackbar()
  const token = useAuthHeader()()
  const client = useQueryClient()

  const mutateFn = ({ clubId, updatedMembers }: PatchMembersMutateParams) =>
    patchMembersAPICall({ clubId, updatedMembers, token })

  return useMutation(mutateFn, {
    onSuccess: () => {
      enqueueSnackbar(CLUB_MEMBER_MESSAGE.PATCH_SUCCESS, {
        variant: 'success'
      })
      client.invalidateQueries('members')
      client.invalidateQueries('honoraryMembers')
    },
    onError: error => {
      if (error instanceof AxiosError) {
        let errorMessage = error.response?.data?.message || COMMON_MESSAGE.SERVER_ERROR
        if (error?.response?.status === 404) {
          errorMessage = CLUB_MEMBER_MESSAGE.NOT_LEVEL_EXIST
        }

        enqueueSnackbar(errorMessage, { variant: 'error' })
      } else {
        enqueueSnackbar(COMMON_MESSAGE.UNKNOWN_ERROR, { variant: 'error' })
      }
    }
  })
}
