import { Link } from 'react-router-dom'

import { Typography, styled, useMediaQuery, useTheme } from '@mui/material'

import LogoSign from 'src/components/LogoSign'

const LogoWrapper = styled(Link)(
  ({ theme }) => `
      display: flex;
      flex-direction: row;
      align-items: center;
      justify-content: center;
      width: fit-content;
      text-decoration: none;
      @media (min-width: ${theme.breakpoints.values.md}px) {
        justify-content: flex-start;
      }
  `
)

const LogoTextWrapper = styled(Typography)(
  ({ theme }) => `
    color: ${theme.palette.text.primary};
    font-size: 22px;
    font-weight: ${theme.typography.fontWeightBold};
    margin: 0;
    @media (min-width: ${theme.breakpoints.values.md}px) {
      display: block;
      margin-left: 6px;
    }
  `
)

function Logo() {
  const theme = useTheme()
  const isPc = useMediaQuery(theme.breakpoints.up('lg'))
  const isNotRegisterPage = window.location.pathname != '/club/register'

  return (
    <LogoWrapper to="/" theme={theme}>
      {isPc && isNotRegisterPage && <LogoSign />}
      <LogoTextWrapper>KLUB</LogoTextWrapper>
    </LogoWrapper>
  )
}

export default Logo
