import { rest } from 'msw'

import RECENT_ACTIVITIES from './data/activities'
import RECRUITS from './data/recruits'

export const HomeHandlers = [
  rest.get('/home/activities/recent', (req, res, ctx) => {
    const limit = Number(req.url.searchParams.get('limit')) || 12
    const limitedData = RECENT_ACTIVITIES.slice(0, limit)

    return res(ctx.status(200), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'), ctx.json(limitedData))
  }),
  rest.get('/home/recruits/recent', (req, res, ctx) => {
    const limit = Number(req.url.searchParams.get('limit')) || 12
    const limitedData = RECRUITS.recruits.slice(0, limit)

    return res(ctx.status(200), ctx.set('Access-Control-Allow-Origin', 'http://localhost:3000'), ctx.json(limitedData))
  })
]
