import axios, { AxiosError, type AxiosResponse } from 'axios'
import { useSnackbar } from 'notistack'
import { useAuthHeader } from 'react-auth-kit'
import { useMutation, useQuery } from 'react-query'

import {
  CLUB_INFORMATION_MESSAGE,
  CLUB_RECRUITMENT_MESSAGE,
  COMMON_MESSAGE,
  DELETE_LIKE_MESSAGE,
  POST_LIKE_MESSAGE,
  SETTING_MESSAGE
} from 'src/data/messages'

import type { Club, ClubId, ClubLike } from 'src/models/club'
import type { MemberLevel } from 'src/models/clubMember'
import type { DateProps } from 'src/models/date'
import type { Recruit, RecruitId } from 'src/models/recruit'
import type { User } from 'src/models/user'

interface ClubInformationParams {
  clubId: ClubId
  token: string
}

export interface PatchClubBody {
  semesterInfo?: DateProps
  searchable?: boolean
}
interface PatchMutationParams {
  clubId: ClubId
  data: PatchClubBody
}
interface PatchParams extends PatchMutationParams {
  token: string
}

const getClubInformation =
  ({ clubId, token }: ClubInformationParams) =>
  async () => {
    const response = await axios.get<Club>(`${process.env.REACT_APP_APIHOST}/club/${clubId}/`, {
      headers: { Authorization: token }
    })
    return response.data
  }

export const useGetClubInformation = (clubId: ClubId) => {
  const { enqueueSnackbar } = useSnackbar()
  const token = useAuthHeader()()

  return useQuery<Club>(['clubInformation', clubId], getClubInformation({ clubId, token }), {
    onError: error => {
      if (error instanceof AxiosError) {
        enqueueSnackbar(error.response?.data?.message ?? CLUB_INFORMATION_MESSAGE.SERVER_ERROR, {
          variant: 'error'
        })
        return
      }
      enqueueSnackbar(CLUB_INFORMATION_MESSAGE.UNKNOWN_ERROR, {
        variant: 'error'
      })
    }
  })
}

export const getCurrentClubRecruitInformation = (clubId: ClubId) => async () => {
  const response = await axios.get<Recruit>(`${process.env.REACT_APP_APIHOST}/club/${clubId}/recruit/`)
  return response.data
}

export const getSpecificClubRecruitInformation = (clubId: ClubId, recruitId: RecruitId) => async () => {
  const response = await axios.get<Recruit>(`${process.env.REACT_APP_APIHOST}/club/${clubId}/recruit/${recruitId}`)
  return response.data
}

export const useGetRecruitInformation = (clubId: ClubId, isMember: boolean, today: Date, recruitId: RecruitId) => {
  const { enqueueSnackbar } = useSnackbar()
  return useQuery<Recruit>(
    'clubRecruitInformation',
    recruitId ? getSpecificClubRecruitInformation(clubId, recruitId) : getCurrentClubRecruitInformation(clubId),
    {
      onError: error => {
        if (error instanceof AxiosError) {
          // if (!isMember) {
          //   enqueueSnackbar(CLUB_RECRUITMENT_MESSAGE.SERVER_ERROR, {
          //     variant: 'warning'
          //   })
          // }
          return
        }
        enqueueSnackbar(CLUB_RECRUITMENT_MESSAGE.UNKNOWN_ERROR, {
          variant: 'error'
        })
      }
    }
  )
}

interface GetClubContentResponse {
  content: string
  imageUrls: string[]
}

const getClubContent = async (clubId: ClubId) => {
  const response = await axios.get<GetClubContentResponse>(`${process.env.REACT_APP_APIHOST}/club/${clubId}/content`)
  return response.data
}

export const useGetClubContent = (clubId: ClubId) => {
  const { enqueueSnackbar } = useSnackbar()

  return useQuery<GetClubContentResponse>(['clubContent', clubId], () => getClubContent(clubId), {
    onError: error => {
      if (error instanceof AxiosError) {
        enqueueSnackbar(error.response?.data?.message ?? COMMON_MESSAGE.SERVER_ERROR, {
          variant: 'error'
        })
        return
      }
      enqueueSnackbar(COMMON_MESSAGE.UNKNOWN_ERROR, {
        variant: 'error'
      })
    }
  })
}

const patchClub = async ({ clubId, token, data }: PatchParams) => {
  await axios.patch<null, AxiosResponse<null>, PatchClubBody>(`${process.env.REACT_APP_APIHOST}/club/${clubId}`, data, {
    headers: { Authorization: token }
  })
}
export const usePatchClub = () => {
  const { enqueueSnackbar } = useSnackbar()
  const token = useAuthHeader()()

  const mutateFn = ({ clubId, data }: PatchMutationParams) => patchClub({ clubId, token, data })

  return useMutation(mutateFn, {
    onSuccess: () => {
      enqueueSnackbar(SETTING_MESSAGE.SUCCESS, { variant: 'success' })
    },
    onError: error => {
      if (error instanceof AxiosError) {
        const errorMessage = error.response?.data?.message || SETTING_MESSAGE.FAIL
        enqueueSnackbar(errorMessage, { variant: 'error' })
      } else {
        enqueueSnackbar(COMMON_MESSAGE.UNKNOWN_ERROR, { variant: 'error' })
      }
    }
  })
}

export interface LikeParams {
  clubId: ClubId
  token: string
}

const postUserLikeInfo =
  ({ clubId, token }: LikeParams) =>
  async () => {
    await axios.post<null, AxiosResponse<null>, null>(
      `${process.env.REACT_APP_APIHOST}/user/like/club/${clubId}/`,
      null,
      {
        headers: { Authorization: token }
      }
    )
  }
export const usePostLikeClub = (clubId: ClubId) => {
  const { enqueueSnackbar } = useSnackbar()
  const token = useAuthHeader()()

  return useMutation(postUserLikeInfo({ clubId, token }), {
    onSuccess: () => {
      enqueueSnackbar(POST_LIKE_MESSAGE.SUCCESS, { variant: 'success' })
    },
    onError: error => {
      if (error instanceof AxiosError) {
        if (error.response?.data?.statusCode == 401) {
          enqueueSnackbar(POST_LIKE_MESSAGE.LOGIN_WARNING, { variant: 'warning' })
        } else {
          const errorMessage = error.response?.data?.message || COMMON_MESSAGE.ADD_FAIL
          enqueueSnackbar(errorMessage, { variant: 'error' })
        }
      } else {
        enqueueSnackbar(COMMON_MESSAGE.UNKNOWN_ERROR, { variant: 'error' })
      }
    }
  })
}
const deleteUserLikeInfo =
  ({ clubId, token }: LikeParams) =>
  async () => {
    await axios.delete<null, AxiosResponse<null>, null>(`${process.env.REACT_APP_APIHOST}/user/like/club/${clubId}`, {
      headers: { Authorization: token }
    })
  }
export const useDeleteLikeClub = (clubId: ClubId) => {
  const { enqueueSnackbar } = useSnackbar()
  const token = useAuthHeader()()

  return useMutation(deleteUserLikeInfo({ clubId, token }), {
    onSuccess: () => {
      enqueueSnackbar(DELETE_LIKE_MESSAGE.SUCCESS, { variant: 'success' })
    },
    onError: error => {
      if (error instanceof AxiosError) {
        const errorMessage = error.response?.data?.message || COMMON_MESSAGE.DELETE_FAIL
        enqueueSnackbar(errorMessage, { variant: 'error' })
      } else {
        enqueueSnackbar(COMMON_MESSAGE.UNKNOWN_ERROR, { variant: 'error' })
      }
    }
  })
}

interface GetResponseData {
  user: Omit<User, 'clubs' | 'likes'>
  clubs: User['clubs']
  likes: User['likes']
}
const getLikeInformation = async (token: string) => {
  const response = await axios.get<GetResponseData>(`${process.env.REACT_APP_APIHOST}/user`, {
    headers: { Authorization: token }
  })

  return response.data.likes
}
export const useGetLike = (isLikeBtnClicked: boolean, likes: ClubLike[]) => {
  const { enqueueSnackbar } = useSnackbar()
  const token = useAuthHeader()()

  // 로그인 상태 아니면 api호출 대신 빈 배열 반환
  if (!token) return useQuery<User['likes']>('like', () => Promise.resolve([]))

  return useQuery<User['likes']>([isLikeBtnClicked, likes], () => getLikeInformation(token), {
    onError: err => {
      if (err instanceof AxiosError) {
        if (err.response?.status !== 401) {
          enqueueSnackbar(err.response?.data?.message ?? COMMON_MESSAGE.SERVER_ERROR, { variant: 'error' })
          return
        } else return
      }
      enqueueSnackbar(COMMON_MESSAGE.UNKNOWN_ERROR, { variant: 'error' })
    }
  })
}

