import { Helmet } from 'react-helmet-async'
import { useParams } from 'react-router'

import WarningIcon from '@mui/icons-material/Warning'
import { Box, Button, CircularProgress, Paper, Typography, useMediaQuery, useTheme } from '@mui/material'

import { useEmailConfirm } from 'src/hooks/api/authHooks'

function Confirm() {
  const theme = useTheme()
  const matches = useMediaQuery(theme.breakpoints.up('sm'))

  const { id: userId } = useParams()
  const emailConfirmQuery = useEmailConfirm(userId ?? '')

  return (
    <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
      <Helmet>
        <title>이메일 인증</title>
      </Helmet>
      <Paper
        square={!matches}
        sx={{
          my: theme.spacing(13),
          padding: 3,
          flex: 1,
          maxWidth: '360px',
          height: { xs: '90vh', sm: 'inherit' },
          [theme.breakpoints.down('sm')]: {
            my: 0,
            py: 5,
            maxWidth: '100%'
          }
        }}
      >
        <Typography component="h1" variant="h3" sx={{ mb: 2, textAlign: 'center' }}>
          사용자 이메일 인증
        </Typography>
        <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
          {emailConfirmQuery.isLoading && <CircularProgress />}
          {emailConfirmQuery.isSuccess && (
            <Box>
              <Typography variant="subtitle1" gutterBottom>
                인증이 완료되었습니다!
              </Typography>
              <Button href="/auth/login" variant="contained">
                KLUB 시작하기
              </Button>
            </Box>
          )}
          {emailConfirmQuery.isError && <WarningIcon fontSize="large" color="warning" />}
        </Box>
      </Paper>
    </Box>
  )
}

export default Confirm
