import LockRoundedIcon from '@mui/icons-material/LockRounded'
import {
  Avatar,
  Divider,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Typography,
  styled
} from '@mui/material'
import type { Theme } from '@mui/material'

import { stringToColor } from 'src/utils'

const LockBadge = styled(LockRoundedIcon)(() => ({
  position: 'absolute',
  top: '55%',
  left: '55%',
  width: '16px',
  height: '16px'
}))

const DrawerHeader = styled('div')(({ theme }) => ({
  // necessary for content to be below app bar
  ...theme.mixins.toolbar,
  display: 'flex',
  alignItems: 'center',
  padding: theme.spacing(0, 1),
  minHeight: theme.header.height,
  height: theme.header.height,
  '@media (min-width: 0px)': {
    minHeight: theme.header.height
  }
}))

interface DrawerItemProps {
  open: boolean
  text: string
  icon: React.ReactElement
  badge?: React.ReactElement
  href: string
  selected: boolean
  theme: Theme
}

const DrawerItem = ({ open, text, icon, badge, href, selected, theme }: DrawerItemProps) => {
  return (
    <ListItem key={text} disablePadding sx={{ display: 'block' }}>
      <ListItemButton
        href={href}
        selected={selected}
        sx={{
          minHeight: 48,
          flexDirection: open ? 'row' : 'column',
          justifyContent: open ? 'initial' : 'center',
          alignItems: 'center',
          px: open ? { base: 1, lg: 2.5 } : 0
        }}
      >
        <ListItemIcon
          sx={{
            position: 'sticky',
            minWidth: 0,
            mr: open ? 3 : 0,
            justifyContent: 'center',
            alignItems: 'center',
            color: selected ? theme.colors.primary.dark : 'default'
          }}
        >
          {icon}
          {badge}
        </ListItemIcon>
        <ListItemText
          primary={text}
          primaryTypographyProps={{
            fontSize: open ? '14px' : '0.6rem',
            color: selected ? theme.colors.primary.dark : 'default'
          }}
          sx={{
            textOverflow: 'ellipsis',
            overflow: 'hidden',
            whiteSpace: 'nowrap'
          }}
        />
      </ListItemButton>
    </ListItem>
  )
}

interface ClubAvatarProps {
  name: string
  profileImageUrl?: string
}

const ClubAvatar = ({ name, profileImageUrl }: ClubAvatarProps) => (
  <Avatar
    src={profileImageUrl}
    children={name[0]}
    sx={{
      width: '32px',
      height: '32px',
      color: stringToColor(name, 0.3, 0.6),
      backgroundColor: stringToColor(name, 0.3)
    }}
  />
)

interface NamedDividerProps {
  open: boolean
  theme: Theme
  children?: React.ReactNode
}

const NamedDivider = ({ open, theme, children }: NamedDividerProps) => (
  <Divider
    children={
      open ? (
        <Typography fontWeight="bold" color={theme.colors.alpha.black[50]}>
          {children}
        </Typography>
      ) : null
    }
    sx={{ my: theme.spacing(open ? 1 : 0) }}
  />
)

export { DrawerItem, ClubAvatar, DrawerHeader, NamedDivider, LockBadge }
